// This file is generated by AI.

import { describe, expect, it } from 'vitest';

import { formatIntermediate, parse, serialize, toWebGALScript } from '../src/model';

describe('parse', () => {
  it('解析旁白 / 对话 / 跟随', () => {
    const { model, diagnostics } = parse(':旁白\n%:对话\n跟随\n:旁白2');
    expect(diagnostics).toEqual([]);
    expect(model.lines.map((l) => [l.kind, l.speaker, l.text, l.follow])).toEqual([
      ['narration', null, '旁白', false],
      ['dialogue', null, '对话', false],
      ['dialogue', null, '跟随', true],
      ['narration', null, '旁白2', false],
    ]);
    expect(model.segments).toEqual([{ head: 1, lines: [1, 2], speaker: null }]);
  });

  it('解析已分配说话者', () => {
    const { model } = parse('张三:你好\n再见');
    expect(model.segments[0].speaker).toBe('张三');
    expect(model.lines[1].follow).toBe(true);
  });

  it('无前缀行跟随旁白产生警告', () => {
    const { diagnostics } = parse(':旁白\n无前缀');
    expect(diagnostics.some((d) => d.severity === 'warning')).toBe(true);
  });

  it('正文含半角冒号产生警告', () => {
    const { diagnostics } = parse(':你好:世界');
    expect(diagnostics.some((d) => d.message.includes('半角冒号'))).toBe(true);
  });

  it('`;` 注释行进入模型 (行号与可见文本一致)', () => {
    const { model } = parse('; 原句\n:旁白\n; 注释 [警告：xxx]\n%:对话');
    expect(model.lines.map((l) => [l.kind, l.text])).toEqual([
      ['comment', '原句'],
      ['narration', '旁白'],
      ['comment', '注释 [警告：xxx]'],
      ['dialogue', '对话'],
    ]);
  });

  it('注释行不影响跟随解析', () => {
    const { model } = parse('; 注释\n%:对话\n; 注释2\n跟随');
    expect(model.lines[3].kind).toBe('dialogue');
    expect(model.lines[3].follow).toBe(true);
    expect(model.segments).toEqual([{ head: 1, lines: [1, 3], speaker: null }]);
  });
});

describe('serialize / formatIntermediate', () => {
  it('序列化回中间格式', () => {
    const text = ':旁白\n%:对话\n跟随';
    expect(serialize(parse(text).model)).toBe(text);
  });

  it('注释行序列化保留 (生成脚本时忽略)', () => {
    const text = '; 原句\n:旁白';
    const { model } = parse(text);
    expect(serialize(model)).toBe(text);
    expect(toWebGALScript(model, { speakers: [] })).toBe(':旁白;');
  });

  it('格式化规整空格并保留前缀', () => {
    expect(formatIntermediate('  :旁白  文本  \n%:对话   内容')).toBe(':旁白 文本\n%:对话 内容');
  });
});

describe('toWebGALScript', () => {
  it('旁白与对话 (含 figureId) 导出', () => {
    const { model } = parse(':旁白\n张三:你好\n再见');
    const script = toWebGALScript(model, { speakers: [{ key: '1', name: '张三', figureId: 'zhang' }] });
    expect(script).toBe(':旁白;\n张三:你好 -figureId=zhang;\n张三:再见 -figureId=zhang;');
  });

  it('未分配对话按旁白导出', () => {
    const { model } = parse('%:未分配');
    expect(toWebGALScript(model, { speakers: [] })).toBe(':未分配;');
  });

  it('编号-名称 说话者导出时去掉编号', () => {
    const { model } = parse('1-小明:你好');
    expect(toWebGALScript(model, { speakers: [{ key: '1', name: '小明' }] })).toBe('小明:你好;');
  });
});
